                                  setSearchAdGroups(prev => prev.map(g => g.id === currentAg.id ? { ...g, ads: [...g.ads, newAd] } : g));
                                  triggerToast(`Added Responsive Search Ad ${newAdNum} to ${currentAg.name}`, "success");
